def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = 18.0 if hp > 3 else 35.0
        return float(max(0.0, min(budget, base)))

    pressure_bids = []
    req_pressure = []
    desperate_count = 0
    rich_count = 0

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid')
        if prev_bid is not None:
            pressure_bids.append(float(prev_bid))
        opp_req = opp.get('water_requirement', WATER_REQ)
        if opp_req > 0:
            req_pressure.append(float(opp_req))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= 120:
            rich_count += 1

    highest_prev = max(pressure_bids) if pressure_bids else 0.0
    avg_prev = sum(pressure_bids) / len(pressure_bids) if pressure_bids else 0.0
    max_req = max(req_pressure) if req_pressure else WATER_REQ

    scarcity_ratio = supply / float(WATER_REQ + max_req)
    low_supply = supply <= 18.0
    severe_scarcity = scarcity_ratio < 1.0

    emergency = hp <= 2 or no_water >= 2
    caution = hp <= 4 or no_water >= 1

    if emergency:
        bid = max(62.0, highest_prev + 4.0, avg_prev + 8.0)
        if severe_scarcity:
            bid = max(bid, 78.0)
        return float(max(0.0, min(budget, bid)))

    if caution:
        if highest_prev >= 120.0:
            bid = 58.0 if not severe_scarcity else 74.0
        else:
            bid = max(46.0, highest_prev + 2.5)
            if low_supply:
                bid += 6.0
        return float(max(0.0, min(budget, bid)))

    if highest_prev >= 135.0:
        bid = 16.0 if hp >= 6 else 28.0
    elif highest_prev >= 100.0:
        bid = 24.0 if not low_supply else 34.0
    elif highest_prev > 0.0:
        bid = max(22.0, min(52.0, highest_prev + 1.5))
    else:
        bid = 26.0

    if severe_scarcity:
        bid += 8.0
    elif low_supply:
        bid += 4.0

    if desperate_count >= 2:
        bid += 4.0
    if rich_count >= 2 and highest_prev >= 90.0:
        bid -= 3.0

    if day >= 8 and hp >= 6:
        bid -= 4.0

    reserve_floor = 12.0 if day < 8 else 0.0
    max_spend = max(0.0, budget - reserve_floor)
    bid = min(bid, max_spend)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_competitors = len(alive_opponents)

    water_slots = int(day_context['supply'] // WATER_REQ)

    # If I'm the only one or competition is minimal, bid low to save budget
    if num_competitors == 0 or (num_competitors == 1 and water_slots >= 2):
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Default bid if no previous bids are available or for initial estimation
    base_bid = DAILY_SALARY * 0.5

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        # High competition detected from yesterday's bids
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 3 or my_status['no_water_days'] >= 1:
                base_bid = DAILY_SALARY * 0.98
            elif num_competitors + 1 > water_slots:
                base_bid = max(DAILY_SALARY * 0.85, highest_prev_bid + 2)
            else:
                base_bid = max(DAILY_SALARY * 0.7, highest_prev_bid * 0.95)
        # Moderate competition
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            if my_status['hp'] <= 3 or my_status['no_water_days'] >= 1:
                base_bid = DAILY_SALARY * 0.9
            elif num_competitors + 1 > water_slots:
                base_bid = max(DAILY_SALARY * 0.7, average_prev_bid + 1)
            else:
                base_bid = max(DAILY_SALARY * 0.55, average_prev_bid + 1)
        # Low competition
        else:
            if my_status['hp'] <= 3 or my_status['no_water_days'] >= 1:
                base_bid = DAILY_SALARY * 0.8
            else:
                base_bid = max(DAILY_SALARY * 0.3, highest_prev_bid + 1)
    else: # No previous bids (e.g., first day of episode)
        if my_status['hp'] <= 3 or my_status['no_water_days'] >= 1:
            base_bid = DAILY_SALARY * 0.9
        else:
            base_bid = DAILY_SALARY * 0.55

    # Adjust bid based on my current health and "no water days"
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        base_bid = max(base_bid, DAILY_SALARY * 0.95)
    elif my_status['hp'] <= 5:
        base_bid = max(base_bid, DAILY_SALARY * 0.75)

    # Consider remaining days, be more aggressive towards the end if needed
    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] < 10:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)

    final_bid = min(my_status['budget'], base_bid)
    final_bid = max(final_bid, 1.0)

    return final_bid

